```go
package solution

import (
    "fmt"
    "strconv"
    "strings"
)

type Counter struct {
    value     int
    completed map[string]int
}

func NewCounter(initial int) *Counter {
    return &Counter{
        value:     initial,
        completed: make(map[string]int),
    }
}

func (c *Counter) Value() int {
    return c.value
}

func (c *Counter) Apply(transactionID, script string) (int, error) {
    if result, ok := c.completed[transactionID]; ok {
        return result, nil
    }

    for _, raw := range strings.Split(script, ";") {
        delta, err := parseStep(strings.TrimSpace(raw))
        if err != nil {
            return c.value, err
        }
        c.value += delta
    }

    c.completed[transactionID] = c.value
    return c.value, nil
}

func parseStep(step string) (int, error) {
    if len(step) < 2 || (step[0] != '+' && step[0] != '-') {
        return 0, fmt.Errorf("malformed step %q", step)
    }
    for i := 1; i < len(step); i++ {
        if step[i] < '0' || step[i] > '9' {
            return 0, fmt.Errorf("malformed step %q", step)
        }
    }

    magnitude, err := strconv.Atoi(step[1:])
    if err != nil {
        return 0, fmt.Errorf("malformed step %q", step)
    }
    if step[0] == '-' {
        magnitude = -magnitude
    }
    return magnitude, nil
}
